1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	import org.springframework.samples.petclinic.util.CityRegions;
12	
13	import java.util.Collection;
14	import java.util.List;
15	
16	/**
17	 * Maps Owner & OwnerDto using Mapstruct
18	 */
19	@Mapper(uses = PetMapper.class)
20	public interface OwnerMapper {
21	
22	    @Mapping(target = "displayName", expression = "java(displayName(owner))")
23	    @Mapping(target = "initials", expression = "java(initials(owner))")
24	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
25	    @Mapping(target = "membershipTier", expression = "java(membershipTier(owner))")
26	    @Mapping(target = "locality", expression = "java(locality(owner))")
27	    @Mapping(target = "sharesHousehold", ignore = true)
28	    OwnerDto toOwnerDto(Owner owner);
29	
30	    /** Format an owner's name as 'LastName, FirstName' for display. */
31	    default String displayName(Owner owner) {
32	        return owner.getLastName() + ", " + owner.getFirstName();
33	    }
34	
35	    /** Upper-cased first letters of first and last name, dot-separated with a trailing dot (e.g. 'J.S.'). */
36	    default String initials(Owner owner) {
37	        return initial(owner.getFirstName()) + initial(owner.getLastName());
38	    }
39	
40	    private static String initial(String name) {
41	        return Character.toUpperCase(name.charAt(0)) + ".";
42	    }
43	
44	    /**
45	     * Derive the membership number '&lt;customerCode&gt;-M&lt;YY&gt;', where YY is the last
46	     * two digits of the registration date year (e.g. 'SYD-SMI-0007-M26'). Returns null when
47	     * either source field is absent.
48	     */
49	    default String membershipNumber(Owner owner) {
50	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
51	            return null;
52	        }
53	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
54	    }
55	
56	    /**
57	     * Derive the membership tier: 'GOLD' when the owner's household has three or more members
58	     * (householdSize is 3+); otherwise 'SILVER' when the owner has no namesakes (namesakeCount is
59	     * 0) and an email is present, otherwise 'BRONZE'.
60	     */
61	    default String membershipTier(Owner owner) {
62	        if (owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3) {
63	            return "GOLD";
64	        }
65	        boolean unique = Integer.valueOf(0).equals(owner.getNamesakeCount());
66	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isEmpty();
67	        return unique && hasEmail ? "SILVER" : "BRONZE";
68	    }
69	
70	    /**
71	     * Derive the owner's locality (canonical region) from their city using the fixed
72	     * city-to-region table, or 'UNKNOWN' when the city is not in the table.
73	     */
74	    default String locality(Owner owner) {
75	        return CityRegions.localityOf(owner.getCity());
76	    }
77	
78	    Owner toOwner(OwnerDto ownerDto);
79	
80	    @Mapping(target = "id", ignore = true)
81	    @Mapping(target = "pets", ignore = true)
82	    Owner toOwner(OwnerFieldsDto ownerDto);
83	
84	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
85	
86	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
87	
88	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
89	        OwnerPageDto ownerPageDto = new OwnerPageDto();
90	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
91	        ownerPageDto.setPage(ownerPage.getNumber());
92	        ownerPageDto.setSize(ownerPage.getSize());
93	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
94	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
95	        return ownerPageDto;
96	    }
97	}
