1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import org.slf4j.Logger;
4	import org.slf4j.LoggerFactory;
5	
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.model.Owner;
8	
9	/**
10	 * Emits an audit trail line for a newly created owner. Runs after {@link SaveOwner} has
11	 * persisted the entity, so the generated id is available, and records the owner id, the
12	 * assigned customer code and the effective registration date on the dedicated {@code AUDIT}
13	 * logger. Purely a side-effect step; it leaves the owner unchanged for the responder.
14	 */
15	public class AuditOwnerCreated {
16	
17	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
18	
19	    public void service(@Val Owner owner) {
20	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={}",
21	                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
22	    }
23	}
