1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Records how many existing owners already share the new owner's first and last name,
9	 * case-insensitively, at the moment of creation. Runs after {@link BuildOwner} has produced
10	 * the entity and before {@link SaveOwner} persists it, so {@code findAll()} sees only the
11	 * owners that existed before this create; the count is stored on the owner and returned on
12	 * every later read.
13	 */
14	public class CountNamesakes {
15	
16	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
17	        String firstName = owner.getFirstName();
18	        String lastName = owner.getLastName();
19	        int count = 0;
20	        for (Owner existing : ownerRepository.findAll()) {
21	            if (firstName.equalsIgnoreCase(existing.getFirstName())
22	                    && lastName.equalsIgnoreCase(existing.getLastName())) {
23	                count++;
24	            }
25	        }
26	        owner.setNamesakeCount(count);
27	    }
28	}
