1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Records how many owners belong to the new owner's household — those sharing its
9	 * {@code householdId} — once this create completes. Runs after {@link AssignHouseholdId} has set
10	 * the id and before {@link SaveOwner} persists the entity, so {@code findAll()} sees only the
11	 * owners that existed before this create; the new owner is counted too by starting from one. The
12	 * size is stored on the owner and drives the membership tier on every later read.
13	 */
14	public class CountHouseholdMembers {
15	
16	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
17	        String householdId = owner.getHouseholdId();
18	        int count = 1;
19	        for (Owner existing : ownerRepository.findAll()) {
20	            if (householdId.equals(existing.getHouseholdId())) {
21	                count++;
22	            }
23	        }
24	        owner.setHouseholdSize(count);
25	    }
26	}
